import{_ as i,a0 as l,w as p,s,ao as d,I as o,x as r,a1 as a,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const I=JSON.parse('{"title":"如何在 Linux 终端中知道你的公有 IP | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 终端中知道你的公有 IP | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 终端中知道你的公有 IP | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 终端中知道你的公有 IP | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150813 How to get Public IP from Linux Terminal","title":"如何在 Linux 终端中知道你的公有 IP","tag":"201508","desc":""},"relativePath":"201508/20150813 How to get Public IP from Linux Terminal.md","filePath":"[post].md"}'),c={name:"201508/20150813 How to get Public IP from Linux Terminal.md"};function u(h,e,m,x,f,g){const t=l("Link");return p(),s("div",null,[e[11]||(e[11]=d(`<h1 id="如何在-linux-终端中知道你的公有-ip" tabindex="-1">如何在 Linux 终端中知道你的公有 IP <a class="header-anchor" href="#如何在-linux-终端中知道你的公有-ip" aria-label="Permalink to “如何在 Linux 终端中知道你的公有 IP”">​</a></h1><p><img src="http://www.blackmoreops.com/wp-content/uploads/2015/06/256x256xHow-to-get-Public-IP-from-Linux-Terminal-blackMORE-Ops.png.pagespeed.ic.GKEAEd4UNr.png" alt=""></p><p>公有地址由 InterNIC 分配并由基于类的网络 ID 或基于 CIDR 的地址块构成（被称为 CIDR 块），并保证了在全球互联网中的唯一性。当公有地址被分配时，其路由将会被记录到互联网中的路由器中，这样访问公有地址的流量就能顺利到达。访问目标公有地址的流量可经由互联网抵达。比如，当一个 CIDR 块被以网络 ID 和子网掩码的形式分配给一个组织时，对应的 [网络 ID，子网掩码] 也会同时作为路由储存在互联网中的路由器中。目标是 CIDR 块中的地址的 IP 封包会被导向对应的位置。</p><p>在本文中我将会介绍在几种在 Linux 终端中查看你的公有 IP 地址的方法。这对普通用户来说并无意义，但 Linux 服务器（无GUI或者作为只能使用基本工具的用户登录时）会很有用。无论如何，从 Linux 终端中获取公有 IP 在各种方面都很意义，说不定某一天就能用得着。</p><p>以下是我们主要使用的两个命令，curl 和 wget。你可以换着用。</p><h3 id="curl-纯文本格式输出" tabindex="-1">Curl 纯文本格式输出: <a class="header-anchor" href="#curl-纯文本格式输出" aria-label="Permalink to “Curl 纯文本格式输出:”">​</a></h3><pre><code>curl icanhazip.com
curl ifconfig.me
curl curlmyip.com
curl ip.appspot.com
curl ipinfo.io/ip
curl ipecho.net/plain
curl www.trackip.net/i
</code></pre><h3 id="curl-json格式输出" tabindex="-1">curl JSON格式输出: <a class="header-anchor" href="#curl-json格式输出" aria-label="Permalink to “curl JSON格式输出:”">​</a></h3><pre><code>curl ipinfo.io/json
curl ifconfig.me/all.json
curl www.trackip.net/ip?json (有点丑陋)
</code></pre><h3 id="curl-xml格式输出" tabindex="-1">curl XML格式输出: <a class="header-anchor" href="#curl-xml格式输出" aria-label="Permalink to “curl XML格式输出:”">​</a></h3><pre><code>curl ifconfig.me/all.xml
</code></pre><h3 id="curl-得到所有ip细节-挖掘机" tabindex="-1">curl 得到所有IP细节 （挖掘机）### <a class="header-anchor" href="#curl-得到所有ip细节-挖掘机" aria-label="Permalink to “curl 得到所有IP细节 （挖掘机）###”">​</a></h3><pre><code>curl ifconfig.me/all
</code></pre><h3 id="使用-dydns-当你使用-dydns-服务时有用" tabindex="-1">使用 DYDNS （当你使用 DYDNS 服务时有用）### <a class="header-anchor" href="#使用-dydns-当你使用-dydns-服务时有用" aria-label="Permalink to “使用 DYDNS （当你使用 DYDNS 服务时有用）###”">​</a></h3><pre><code>curl -s &#39;http://checkip.dyndns.org&#39; | sed &#39;s/.*Current IP Address: \\([0-9\\.]*\\).*/\\1/g&#39; 
curl -s http://checkip.dyndns.org/ | grep -o &quot;[[:digit:].]\\+&quot;
</code></pre><h3 id="使用-wget-代替-curl" tabindex="-1">使用 Wget 代替 Curl <a class="header-anchor" href="#使用-wget-代替-curl" aria-label="Permalink to “使用 Wget 代替 Curl”">​</a></h3><pre><code>wget http://ipecho.net/plain -O - -q ; echo
wget http://observebox.com/ip -O - -q ; echo
</code></pre><h3 id="使用-host-和-dig-命令" tabindex="-1">使用 host 和 dig 命令 <a class="header-anchor" href="#使用-host-和-dig-命令" aria-label="Permalink to “使用 host 和 dig 命令”">​</a></h3><p>如果有的话，你也可以直接使用 host 和 dig 命令。</p><pre><code>host -t a dartsclink.com | sed &#39;s/.*has address //&#39;
dig +short myip.opendns.com @resolver1.opendns.com
</code></pre><h3 id="bash-脚本示例" tabindex="-1">bash 脚本示例: <a class="header-anchor" href="#bash-脚本示例" aria-label="Permalink to “bash 脚本示例:”">​</a></h3><pre><code>#!/bin/bash

PUBLIC_IP=\`wget http://ipecho.net/plain -O - -q ; echo\`
echo $PUBLIC_IP
</code></pre><p>简单易用。</p><p>我实际上是在写一个用于记录每日我的路由器中所有 IP 变化并保存到一个文件的脚本。我在搜索过程中找到了这些很好用的命令。希望某天它能帮到其他人。</p><hr>`,25)),o("p",null,[e[1]||(e[1]=r("via: ",-1)),a(t,{href:"http://www.blackmoreops.com/2015/06/14/how-to-get-public-ip-from-linux-terminal/"},{default:n(()=>[...e[0]||(e[0]=[r("http://www.blackmoreops.com/2015/06/14/how-to-get-public-ip-from-linux-terminal/",-1)])]),_:1})]),o("p",null,[e[4]||(e[4]=r("译者：",-1)),a(t,{href:"https://github.com/KevinSJ"},{default:n(()=>[...e[2]||(e[2]=[r("KevinSJ",-1)])]),_:1}),e[5]||(e[5]=r(" 校对：",-1)),a(t,{href:"https://github.com/wxy"},{default:n(()=>[...e[3]||(e[3]=[r("wxy",-1)])]),_:1})]),o("p",null,[e[8]||(e[8]=r("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[6]||(e[6]=[r("LCTT",-1)])]),_:1}),e[9]||(e[9]=r(" 原创翻译，",-1)),a(t,{href:"https://linux.cn/"},{default:n(()=>[...e[7]||(e[7]=[r("Linux中国",-1)])]),_:1}),e[10]||(e[10]=r(" 荣誉推出",-1))])])}const w=i(c,[["render",u]]);export{I as __pageData,w as default};
